27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ then 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "membership_number")
61	    private String membershipNumber;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
70	    private Set<Pet> pets;
71	
72	    public String getAddress() {
73	        return this.address;
74	    }
75	
76	    public void setAddress(String address) {
77	        this.address = address;
78	    }
79	
80	    public String getCity() {
81	        return this.city;
82	    }
83	
84	    public void setCity(String city) {
85	        this.city = city;
86	    }
87	
88	    public String getTelephone() {
89	        return this.telephone;
90	    }
91	
92	    public void setTelephone(String telephone) {
93	        this.telephone = telephone;
94	    }
95	
96	    public String getEmail() {
97	        return this.email;
98	    }
99	
100	    public void setEmail(String email) {
101	        this.email = email;
102	    }
103	
104	    public LocalDate getRegistrationDate() {
105	        return this.registrationDate;
106	    }
107	
108	    public void setRegistrationDate(LocalDate registrationDate) {
109	        this.registrationDate = registrationDate;
110	    }
111	
112	    public String getCustomerCode() {
113	        return this.customerCode;
114	    }
115	
116	    public void setCustomerCode(String customerCode) {
117	        this.customerCode = customerCode;
118	    }
119	
120	    public String getMembershipNumber() {
121	        return this.membershipNumber;
122	    }
123	
124	    public void setMembershipNumber(String membershipNumber) {
125	        this.membershipNumber = membershipNumber;
126	    }
127	
128	    public String getHouseholdId() {
129	        return this.householdId;
130	    }
131	
132	    public void setHouseholdId(String householdId) {
133	        this.householdId = householdId;
134	    }
135	
136	    public Integer getNamesakeCount() {
137	        return this.namesakeCount;
138	    }
139	
140	    public void setNamesakeCount(Integer namesakeCount) {
141	        this.namesakeCount = namesakeCount;
142	    }
143	
144	    /**
145	     * The owner's membership tier: {@code "SILVER"} when {@code namesakeCount} is 0 and an email is
146	     * present, otherwise {@code "BRONZE"}.
147	     */
148	    public String getMembershipTier() {
149	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
150	        boolean hasEmail = this.email != null && !this.email.isBlank();
151	        return unique && hasEmail ? "SILVER" : "BRONZE";
152	    }
153	
154	    /**
155	     * Fixed city-to-region table mapping each known city to its canonical region string.
156	     */
157	    private static final Map<String, String> CITY_REGION = Map.of(
158	        "Sydney", "NSW",
159	        "Melbourne", "VIC",
160	        "Brisbane", "QLD");
161	
162	    /**
163	     * The owner's locality: the canonical region derived from {@link #getCity() city} via the fixed
164	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
165	     * {@code "UNKNOWN"} when the city is not in the table.
166	     */
167	    public String getLocality() {
168	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
169	    }
170	
171	    protected Set<Pet> getPetsInternal() {
172	        if (this.pets == null) {
173	            this.pets = new HashSet<>();
174	        }
175	        return this.pets;
176	    }
177	
178	    protected void setPetsInternal(Set<Pet> pets) {
179	        this.pets = pets;
180	    }
181	
182	    public List<Pet> getPets() {
183	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
184	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
185	        return Collections.unmodifiableList(sortedPets);
186	    }
187	
188	    public void setPets(List<Pet> pets) {
189	        this.pets = new HashSet<>(pets);
190	    }
191	
192	    public void addPet(Pet pet) {
193	        getPetsInternal().add(pet);
194	        pet.setOwner(this);
195	    }
196	
197	    /**
198	     * Return the Pet with the given name, or null if none found for this Owner.
199	     *
200	     * @param name to test
201	     * @return true if pet name is already in use
202	     */
203	    public Pet getPet(String name) {
204	        return getPet(name, false);
205	    }
206	
207	    /**
208	     * Return the Pet with the given name, or null if none found for this Owner.
209	     *
210	     * @param name to test
211	     * @return true if pet name is already in use
212	     */
213	    public Pet getPet(String name, boolean ignoreNew) {
214	        name = name.toLowerCase();
215	        for (Pet pet : getPetsInternal()) {
216	            if (!ignoreNew || !pet.isNew()) {
217	                String compName = pet.getName();
218	                compName = compName.toLowerCase();
219	                if (compName.equals(name)) {
220	                    return pet;
221	                }
222	            }
223	        }
224	        return null;
225	    }
226	
227	    public Pet getPet(Integer petId) {
228	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
229	    }
230	
231	    @Override
232	    public String toString() {
233	        return new ToStringCreator(this)
234	
235	            .append("id", this.getId())
236	            .append("new", this.isNew())
237	            .append("lastName", this.getLastName())
238	            .append("firstName", this.getFirstName())
239	            .append("address", this.address)
240	            .append("city", this.city)
241	            .append("telephone", this.telephone)
242	            .toString();
243	    }
244	}
