1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects a new owner whose E.164 telephone is already used by another owner, so the request is
11	 * answered with a 409 Conflict rather than persisting a duplicate. Runs after {@link ValidateNewOwner}
12	 * (which has already normalized the request telephone to E.164) and before {@link BuildOwner}.
13	 *
14	 * <p>Stored telephones are normalized to E.164 the same way before comparison so seed data that was
15	 * not stored in E.164 form still collides with an equivalent request.
16	 */
17	public class CheckTelephoneUnique {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateTelephoneException {
21	        String telephone = request.getTelephone();
22	        for (Owner existing : ownerRepository.findAll()) {
23	            String existingTelephone = existing.getTelephone();
24	            if (existingTelephone != null
25	                    && telephone.equals(OwnerTelephone.toE164(existingTelephone))) {
26	                throw new DuplicateTelephoneException(telephone);
27	            }
28	        }
29	    }
30	}
31

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a new owner who belongs to the same household as an existing owner — same last name and same
11	 * address — so the request is answered with a 409 Conflict rather than persisting a duplicate household
12	 * member. Last name and address are compared case-insensitively with surrounding and internal whitespace
13	 * collapsed, so "Smith" / " smith " and "10  Main St" / "10 Main St" collide.
14	 *
15	 * <p>The caller can opt in to sharing a household by setting {@code sharesHousehold} true on the request,
16	 * which skips this check (e.g. a spouse or flatmate registering under the same roof). Runs after
17	 * {@link CheckTelephoneUnique} and before {@link BuildOwner}.
18	 */
19	public class CheckHouseholdUnique {
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws DuplicateHouseholdException {
23	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            return;
25	        }
26	        String key = Household.key(request.getLastName(), request.getAddress());
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (key.equals(Household.key(existing.getLastName(), existing.getAddress()))) {
29	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
30	            }
31	        }
32	    }
33	}
