1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
8	
9	/**
10	 * Rejects a new owner whose city already contains {@link #CAPACITY} or more owners, so the request is
11	 * answered with a 409 Conflict rather than exceeding the per-city capacity. Cities are compared in
12	 * their {@link OwnerCity#normalize normalized} form (whitespace collapsed, lower-cased), consistent
13	 * with the other create-time checks. Runs after {@link CheckHouseholdUnique} and before
14	 * {@link BuildOwner}.
15	 */
16	public class CheckCityCapacity {
17	
18	    /** Maximum number of owners permitted per city. */
19	    static final int CAPACITY = 50;
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws CityAtCapacityException {
23	        String city = request.getCity();
24	        String normalizedCity = OwnerCity.normalize(city);
25	        int count = 0;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (normalizedCity.equals(OwnerCity.normalize(existing.getCity()))) {
28	                count++;
29	            }
30	        }
31	        if (count >= CAPACITY) {
32	            throw new CityAtCapacityException(city, CAPACITY);
33	        }
34	    }
35	}
