1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DailyLimitExceededException;
10	
11	/**
12	 * Rejects a new owner once {@link #DAILY_LIMIT} or more owners have already been created for its
13	 * registration day, so the request is answered with a 429 Too Many Requests rather than exceeding the
14	 * daily cap. The cap is counted per adjusted business day: the request's effective registration date
15	 * (supplied, or the server date when omitted) is rolled forward over weekends exactly as
16	 * {@link BuildOwner} will store it, so stored owners already carry the same adjusted dates. Runs among
17	 * the create-time checks, before {@link BuildOwner}.
18	 */
19	public class CheckDailyLimit {
20	
21	    /** Maximum number of owners that may be created in a single day. */
22	    static final int DAILY_LIMIT = 100;
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DailyLimitExceededException {
26	        LocalDate businessDay = RegistrationDates.effective(request.getRegistrationDate());
27	        int count = 0;
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (businessDay.equals(existing.getRegistrationDate())) {
30	                count++;
31	            }
32	        }
33	        if (count >= DAILY_LIMIT) {
34	            throw new DailyLimitExceededException(DAILY_LIMIT);
35	        }
36	    }
37	}
