3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Shared rules for an owner's registration date. The <em>effective</em> registration date is the one
8	 * supplied in the request, or the server's current date when none was supplied; it must always fall on
9	 * a business day, so a Saturday or Sunday is rolled forward to the next Monday. Every value derived from
10	 * the registration date (the stored {@code registrationDate}, the membership number's year segment and
11	 * the per-day create-limit bucket) is computed from this adjusted date.
12	 */
13	final class RegistrationDates {
14	
15	    private RegistrationDates() {
16	    }
17	
18	    /**
19	     * The effective, business-day registration date: {@code supplied} when non-null, otherwise the
20	     * server's current date, rolled forward to the next Monday when it lands on a weekend.
21	     */
22	    static LocalDate effective(LocalDate supplied) {
23	        return toBusinessDay(supplied != null ? supplied : LocalDate.now());
24	    }
25	
26	    /** Roll a weekend date forward to the next Monday; a weekday is returned unchanged. */
27	    static LocalDate toBusinessDay(LocalDate date) {
28	        if (date.getDayOfWeek() == DayOfWeek.SATURDAY) {
29	            return date.plusDays(2);
30	        }
31	        if (date.getDayOfWeek() == DayOfWeek.SUNDAY) {
32	            return date.plusDays(1);
33	        }
34	        return date;
35	    }
36	}
