1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Single source of truth for what a "normalized" owner address is. Both {@link ValidateNewOwner}
8	 * (which enforces the rule and stores the normalized value) and {@link Household} (which compares
9	 * addresses for duplicate detection and the shared household id) normalize through here, so the
10	 * duplicate check, the stored/returned value and the household id can never drift apart.
11	 *
12	 * <p>Normalization:
13	 * <ul>
14	 *   <li>trims and collapses runs of whitespace to a single space;</li>
15	 *   <li>upper-cases (locale-independent);</li>
16	 *   <li>expands common abbreviations as whole words: {@code ST -> STREET}, {@code RD -> ROAD},
17	 *       {@code AVE -> AVENUE}.</li>
18	 * </ul>
19	 * A {@code null} or all-whitespace input normalizes to the empty string, which callers treat as a
20	 * blank (and therefore missing) address.
21	 */
22	final class OwnerAddress {
23	
24	    /** Whole-word abbreviations expanded during normalization (keys are already upper-cased). */
25	    private static final Map<String, String> ABBREVIATIONS = Map.of(
26	            "ST", "STREET",
27	            "RD", "ROAD",
28	            "AVE", "AVENUE");
29	
30	    private OwnerAddress() {
31	    }
32	
33	    /**
34	     * Returns the normalized form of {@code address}, or the empty string when it is {@code null} or
35	     * blank after trimming.
36	     */
37	    static String normalize(String address) {
38	        if (address == null) {
39	            return "";
40	        }
41	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
42	        if (collapsed.isEmpty()) {
43	            return "";
44	        }
45	        String[] tokens = collapsed.split(" ");
46	        StringBuilder sb = new StringBuilder(collapsed.length());
47	        for (int i = 0; i < tokens.length; i++) {
48	            if (i > 0) {
49	                sb.append(' ');
50	            }
51	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
52	        }
53	        return sb.toString();
54	    }
55	}
